using IndieRun;
using System.IO;
using System.Reflection;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using System.Xml.Linq;
class Program
{
    static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
    static void Set(object o,string field,object? value)=>o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(o,value);
    static T Get<T>(object o,string field)=>(T)o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(o)!;
    static object? Call(object o,string method,params object?[] args)=>o.GetType().GetMethod(method,BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.DeclaredOnly)!.Invoke(o,args);
    static Package Fixture(string dir,bool selective=false)
    {
        var folder=Path.Combine(dir,"input","GeneratedGame");Directory.CreateDirectory(Path.Combine(folder,"Data"));Directory.CreateDirectory(Path.Combine(folder,"Extras"));
        File.WriteAllText(Path.Combine(folder,"Game.exe"),"harmless generated fixture; never execute");File.WriteAllBytes(Path.Combine(folder,"Data","large.bin"),Enumerable.Range(0,1536*1024).Select(i=>(byte)(i%251)).ToArray());File.WriteAllText(Path.Combine(folder,"Extras","guide.txt"),"kept or moved according to selection");
        var p=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=false,Source=folder,DetectedRoot=folder,SearchRoot=Path.Combine(dir,"input"),Name="GeneratedGame",Folder="GeneratedGame",Alias="가상 게임"};if(selective)p.OmittedFolders.Add("Extras");return p;
    }
    static MainWindow Window(string dir,out Package p)
    {
        p=Fixture(dir);var scan=GameScanner.Scan(p.SearchRoot);scan.PrepareIndex();var plan=new WorkspaceDocument{SearchRoot=p.SearchRoot,SearchLocations=[new(){Path=p.SearchRoot}],Destination=Path.Combine(dir,"library"),BackupRoot=Path.Combine(dir,"backups"),Packages=[p],Checkpoints=[WorkspaceReconciler.Capture(p,scan)]};var store=new WorkspaceStore(Path.Combine(dir,"data","workspace.json"));store.Save(plan);
        var w=new MainWindow();new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();Set(w,"workspaceStore",store);Set(w,"workspaceLock",store.AcquireLock());Call(w,"ApplyWorkspace",plan);Set(w,"snapshot",scan);Set(w,"sessionReady",true);Set(w,"playerRoot",plan.Destination);Set(w,"playerDocument",new PlayerDocument());Set(w,"directEngineFactory",(Func<BackupEngine>)(()=>new(Path.Combine(dir,"records"))));return w;
    }
    static void Close(MainWindow w){Set(w,"closingWithoutSave",true);w.Close();}
    static IEnumerable<DependencyObject> Logical(DependencyObject root){yield return root;foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var nested in Logical(child))yield return nested;}
    static void Wait(Task task){var frame=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();}
    static void Click(Button b)=>b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
    static void Toggle(System.Windows.Controls.Primitives.ToggleButton b,bool value){b.IsChecked=value;b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
    static Button FindButton(Window w,string text)=>Logical((DependencyObject)w.Content).OfType<Button>().Single(b=>b.Content as string==text);
    static T Named<T>(Window w,string name)where T:FrameworkElement=>Logical((DependencyObject)w.Content).OfType<T>().Single(e=>e.Name==name);
    static void Layout(Window w,double width,double height,string file){var body=(FrameworkElement)w.Content;body.Measure(new Size(width,height));body.Arrange(new Rect(0,0,width,height));body.UpdateLayout();foreach(var b in Logical(body).OfType<Button>().Where(b=>b.IsVisible||b.ActualWidth>0)){var point=b.TranslatePoint(new Point(),body);Check(point.X>=-1&&point.X+b.ActualWidth<=width+1,"Button clipped horizontally: "+b.Content);}var bitmap=new RenderTargetBitmap((int)width,(int)height,96,96,PixelFormats.Pbgra32);var bg=new DrawingVisual();using(var draw=bg.RenderOpen())draw.DrawRectangle(w.Background,null,new Rect(0,0,width,height));bitmap.Render(bg);bitmap.Render(body);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(file);png.Save(output);}
    static Package Second(MainWindow w,string dir){var p=Fixture(Path.Combine(dir,"second"));p.Alias="두 번째 가상 게임";Get<List<Package>>(w,"packages").Add(p);var scan=GameScanner.Scan(dir);Set(w,"snapshot",scan);Set(w,"checkpoints",Get<List<Package>>(w,"packages").Select(g=>WorkspaceReconciler.Capture(g,scan)).ToList());return p;}
    static IntakeSelection Plan(MainWindow w,List<Package> games)=>new(new MoveSelection(games,Get<List<Package>>(w,"packages")));
    static LibraryDocument Registered(Package p)=>new(){Games=[new(){Id=p.Id,Folder=p.Folder,LastKnownPath=p.Source,Executables=["Game.exe"],Scope=StoredScope.Capture(p)}]};
    static (Package Game,string Parent,string Search,ScanSnapshot Scan,FolderCheckpoint Checkpoint) Game(string dir,bool marked=true)
    {
        var search=Path.Combine(dir,"container");var parent=Path.Combine(search,"外側パッケージ","ゲーム名");var data=Path.Combine(parent,"data");Directory.CreateDirectory(data);File.WriteAllText(Path.Combine(data,"Game.exe"),"harmless generated fixture; never execute");File.WriteAllText(Path.Combine(data,"save.dat"),"test save");
        var p=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=marked,Source=data,DetectedRoot=data,SearchRoot=search,Name="data",Folder="data"};if(marked)LibraryStore.EnsureIdentity(data,p.Id);var scan=GameScanner.Scan(search);scan.SearchRoots.Add(search);scan.PrepareIndex();return(p,parent,search,scan,WorkspaceReconciler.Capture(p,scan));
    }
    static string RenameParent(string parent){var renamed=Path.Combine(Path.GetDirectoryName(parent)!,"ゲーム名5555");Directory.Move(parent,renamed);return Path.Combine(renamed,"data");}
    static string Refusal(Action run){try{run();}catch(IOException e){return e.Message;}throw new Exception("Expected refusal");}
    static WorkspaceDocument Plan(string dir,Package p,FolderCheckpoint check,params Package[] others)=>new(){SearchRoot=p.SearchRoot,SearchLocations=[new(){Path=p.SearchRoot}],Destination=Path.Combine(dir,"library"),BackupRoot=Path.Combine(dir,"backups"),Packages=new[]{p}.Concat(others).ToList(),Checkpoints=[check]};
    static Package Helper(string parent)=>new(){Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=false,Source=parent,DetectedRoot=parent,SearchRoot=Path.GetDirectoryName(parent)!,Folder=Path.GetFileName(parent),Name=Path.GetFileName(parent)};
    static ScanSnapshot Scan(string root){var scan=GameScanner.Scan(root);scan.SearchRoots.Add(root);scan.PrepareIndex();return scan;}

    [STAThread] static int Main(string[] args)
    {
        var root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var results=new List<object>();int failed=0;
        void Test(string name,Action<string> run){var dir=Path.Combine(root,Guid.NewGuid().ToString("N")[..8]);Directory.CreateDirectory(dir);try{run(dir);results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;results.Add(new{name,passed=false,error=ex.ToString()});Console.WriteLine("FAIL "+name+" "+ex.Message);}}
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());
        void CaptureModal(Action invoke,string screenshot){bool seen=false;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(20)};timer.Tick+=(_,_)=>{if(seen)return;var dialog=Application.Current.Windows.OfType<AppDialog>().LastOrDefault();if(dialog==null)return;seen=true;Layout(dialog,600,450,screenshot);dialog.Close();};timer.Start();try{invoke();}finally{timer.Stop();}Check(seen,"Expected dialog did not appear");}
        void Export(MainWindow w,Package p,bool legacy=false){LibraryStore.EnsureIdentity(p.Source,p.Id);p.OmittedFolders=["Extras"];p.Contents=[new(){Path="Extras",Role="exclude"}];p.ScopeReviewRequired=legacy;PortableStore.Export(Path.GetDirectoryName(p.Source)!,p.Folder,p,new(){Id=p.Id},new(),Get<string>(w,"destination"));p.OmittedFolders=[];p.Contents=[];p.ScopeReviewRequired=false;var scan=GameScanner.Scan(p.SearchRoot);Set(w,"snapshot",scan);Set(w,"identityInventory",LibraryStore.Inspect(scan));Set(w,"checkpoints",new List<FolderCheckpoint>{WorkspaceReconciler.Capture(p,scan)});}
        Test("portable-import-preserves-exclusion-in-live-state-and-next-save",dir=>{var w=Window(dir,out var p);try{Export(w,p);Call(w,"ImportPortableGames",new HashSet<string>(),Get<ScanSnapshot>(w,"snapshot"));Check(!p.Includes(Path.Combine(p.Source,"Extras","guide.txt"))&&!p.ScopeReviewRequired,"Imported live scope includes excluded content");var check=Get<List<FolderCheckpoint>>(w,"checkpoints").Single();Check(!check.Files.Any(f=>f.RelativePath.StartsWith("Extras")),"Checkpoint includes excluded files");Check((bool)Call(w,"FlushWorkspace")!,"Flush failed");var saved=Get<WorkspaceStore>(w,"workspaceStore").Load().Document!;Check(saved.Packages.Single().OmittedFolders.SequenceEqual(new[]{"Extras"}),"Next save overwrote imported scope");Check(new LibraryStore(Get<string>(w,"destination")).Load().Games.Single().Scope!.OmittedFolders.SequenceEqual(new[]{"Extras"}),"Library scope differs");}finally{Close(w);}});
        Test("legacy-portable-scope-stays-unconfirmed-in-live-ui",dir=>{var w=Window(dir,out var p);try{Export(w,p,true);Call(w,"ImportPortableGames",new HashSet<string>(),Get<ScanSnapshot>(w,"snapshot"));Check(p.ScopeReviewRequired&&p.ReviewState=="scope","Legacy scope silently accepted in UI");Check((bool)Call(w,"FlushWorkspace")!,"Flush failed");Check(Get<WorkspaceStore>(w,"workspaceStore").Load().Document!.Packages.Single().ScopeReviewRequired,"Unknown scope lost on save");}finally{Close(w);}});
        Test("automatic-save-retains-outside-scan-id-conflict",dir=>{var w=Window(dir,out var p);try{LibraryStore.EnsureIdentity(p.Source,p.Id);var other=Path.Combine(dir,"known-copy");Directory.CreateDirectory(other);File.Copy(Path.Combine(p.Source,LibraryStore.MarkerName),Path.Combine(other,LibraryStore.MarkerName));var scan=GameScanner.Scan(p.SearchRoot);Set(w,"snapshot",scan);Set(w,"checkpoints",new List<FolderCheckpoint>{WorkspaceReconciler.Capture(p,scan)});var store=new LibraryStore(Get<string>(w,"destination"));store.Update(d=>d.Games.Add(new(){Id=p.Id,Folder=p.Folder,LastKnownPath=p.Source,Scope=StoredScope.Capture(p),Executables=["Game.exe"]}));Set(w,"libraryDocument",store.Load());var inventory=LibraryStore.Inspect(scan);inventory.Locations[p.Id].Add(other);Set(w,"identityInventory",inventory);Call(w,"SaveLibraryMetadata");Check(Get<IdentityInventory>(w,"identityInventory").Locations[p.Id].Count==2,"Save discarded known copy");Check(store.Load().Games.Single().Status=="Duplicate","Save hid identity conflict");}finally{Close(w);}});
        Test("csv-save-problem-has-actionable-dialog-and-recovers",dir=>{var w=Window(dir,out var p);try{Check((bool)Call(w,"RegisterGame",p,true)!,"Registration failed");var csv=Path.Combine(Get<string>(w,"destination"),LibraryStore.CsvName);File.WriteAllText(csv,"generated foreign CSV; preserve");Check((bool)Call(w,"FlushWorkspace")!,"Workspace save unexpectedly failed");Check(Get<string>(w,"libraryError").Length>0,"CSV error hidden");CaptureModal(()=>Call(w,"SaveStatus_Click",w,new RoutedEventArgs()),Path.Combine(root,"metadata-save-warning.png"));Check(File.ReadAllText(csv).StartsWith("generated foreign"),"Foreign CSV overwritten");File.Delete(csv);Check((bool)Call(w,"FlushWorkspace")!&&Get<string>(w,"libraryError").Length==0&&Get<Button>(w,"SaveStatus").Content?.ToString()=="저장됨 ✓","Retry did not clear warning");}finally{Close(w);}});
        Test("metadata-save-action-does-not-claim-write-before-scan",dir=>{var w=Window(dir,out var p);try{Check((bool)Call(w,"RegisterGame",p,true)!,"Registration failed");Set(w,"snapshot",null);Call(w,"RenderLibrary");var button=Logical(Get<StackPanel>(w,"LibraryContent")).OfType<Button>().Single(b=>b.Content as string=="정보 파일 · CSV 저장");Check(!button.IsEnabled&&button.ToolTip!=null,"No-op save button claims success");}finally{Close(w);}});
        Test("composition-keeps-folders-after-first-150-accessible",dir=>{var w=Window(dir,out var p);Window? editor=null;try{for(int i=0;i<170;i++)Directory.CreateDirectory(Path.Combine(p.Source,"Section"+i.ToString("D3")));Set(w,"snapshot",GameScanner.Scan(p.SearchRoot));editor=(Window)Call(w,"BuildCompositionEditor",p)!;new System.Windows.Interop.WindowInteropHelper(editor).EnsureHandle();Layout(editor,800,600,Path.Combine(root,"composition-paged-folders.png"));var tree=Named<TreeView>(editor,"CompositionTree");var parent=(TreeViewItem)tree.Items[0];Check(parent.Items.Count==151,"Initial list is unbounded or truncated without more");var more=(Button)((TreeViewItem)parent.Items[parent.Items.Count-1]).Header;Click(more);Check(parent.Items.OfType<TreeViewItem>().Any(n=>n.Tag as string==Path.Combine(p.Source,"Section169")),"Later folder unreachable");var last=parent.Items.OfType<TreeViewItem>().Single(n=>n.Tag as string==Path.Combine(p.Source,"Section169"));last.IsSelected=true;var assign=Logical((DependencyObject)editor.Content).OfType<Button>().Single(b=>b.Content as string=="포함하지 않음");Click(assign);parent=(TreeViewItem)tree.Items[0];Check(parent.Items.OfType<TreeViewItem>().Any(n=>n.Tag as string==Path.Combine(p.Source,"Section169")),"Editing reset expanded page");}finally{if(editor!=null){var closer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(20)};closer.Tick+=(_,_)=>{var d=Application.Current.Windows.OfType<AppDialog>().LastOrDefault();if(d!=null)Click(d.ActionButtons.Last());};closer.Start();try{editor.Close();}finally{closer.Stop();}}Close(w);}});
        Test("pending-edit-can-recover-from-save-warning-without-global-scan",dir=>{var w=Window(dir,out var p);try{var data=Path.Combine(dir,"data");Set(w,"tagStore",new TagCatalogStore(Path.Combine(data,"tags.json")));var plan=Get<WorkspaceStore>(w,"workspaceStore").Load().Document!;plan.Packages.Single().Alias="복구된 가상 게임";var edit=new EditTransaction(data);typeof(EditTransaction).GetProperty("Checkpoint",BindingFlags.Instance|BindingFlags.NonPublic)!.SetValue(edit,(Action<string>)(phase=>{if(phase=="intent")throw new IOException("Generated interruption");}));try{edit.Commit(new(){Plan=plan,Tags=new(),Play=new()});}catch(IOException){}Check(File.Exists(edit.Pending),"No pending edit fixture");Set(w,"workspaceBlocked",true);CaptureModal(()=>Call(w,"ShowWorkspaceSaveIssue"),Path.Combine(root,"pending-edit-recovery.png"));var recovered=(Task<bool>)Call(w,"RecoverPendingEditAsync")!;Wait(recovered);Check(recovered.Result&&!File.Exists(edit.Pending)&&!Get<bool>(w,"workspaceBlocked"),"Pending edit remains blocked");Check(Get<List<Package>>(w,"packages").Single().Alias=="복구된 가상 게임"&&Get<ScanSnapshot?>(w,"snapshot")==null&&!Get<bool>(w,"scanning"),"Recovery lost edit or restarted entire scan");}finally{Close(w);}});
        Test("library-error-details-are-collapsed-with-visible-action",dir=>{var w=Window(dir,out var p);try{Set(w,"libraryError","가상 저장 오류 · "+new string('x',300));var inventory=new IdentityInventory();inventory.Problems.Add(new(p.Source,"가상 ID 오류"));Set(w,"identityInventory",inventory);Call(w,"SetPage","library");Call(w,"RenderLibrary");var panel=Get<StackPanel>(w,"LibraryContent");Check(Logical(panel).OfType<Expander>().All(e=>!e.IsExpanded)&&Logical(panel).OfType<Button>().Any(b=>b.Content as string=="저장 문제 확인"),"Errors expose long details or no action");Layout(w,1180,780,Path.Combine(root,"library-error-summary.png"));}finally{Close(w);}});
        Test("portable-retry-after-recovery-without-snapshot-is-explained",dir=>{var w=Window(dir,out var p);try{Set(w,"snapshot",null);CaptureModal(()=>Call(w,"RetryPortable_Click",w,new RoutedEventArgs()),Path.Combine(root,"portable-recheck-needed.png"));Check(Get<ScanSnapshot?>(w,"snapshot")==null&&!File.Exists(Path.Combine(p.Source,LibraryStore.MarkerName)),"Retry wrote identity without scanning");}finally{Close(w);}});
        File.WriteAllText(args[1],JsonSerializer.Serialize(new{total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));return failed==0?0:1;
    }
}
